// ชุดเริ่มต้นฟรี (handover §6): สีผิว/สีผมทุกสี · ผม 3 · ตา 2 · ปาก 2 · เสื้อ 2 (รวมเชิ้ตนักศึกษา) · ท่อนล่าง 2 · รองเท้า 1
export const FREE = new Set(['h1', 'h2', 'h3', 'e1', 'e2', 'm1', 'm5', 't1', 't5', 'b2', 'b4', 'k1'])
// 19 พ.ย. user: ของธรรมดาไม่ต้องแพง · ของแพง (ปีก/ชุดโชว์) มีออร่า
const THEME_PRICE = { basic: 3000, uniform: 10000, sport: 10000, fashion: 15000, cute: 15000, fantasy: 60000 }
const PRICE_OVERRIDE = {
  // ชุดสัตว์เต็มตัว แพงกว่าเสื้อทั่วไป (ฮู้ดราคาปกติของ cute)
  n1: 60000, x41: 150000,
  f19: 400000, f20: 400000, f21: 400000, f22: 400000, x39: 150000, x40: 150000,
  f14: 300000, f15: 300000, f16: 300000, f17: 300000, f18: 300000, x27: 80000,
  f5: 30000, f9: 30000, f10: 30000, f11: 30000, f12: 30000, f13: 30000,
  // ชุดเต็มตัวแฟนซี + ปีก = ของโชว์
  f3: 400000, f6: 400000, w1: 1200000, w2: 1200000, w3: 1500000, w4: 1500000, w5: 2000000, w6: 450000, w7: 1200000,
}
// 🧑 ลักษณะตัวละคร (ตา ปาก หนวด/เครา) ฟรีหมด — user 19 พ.ย. · ยกเว้นทรงผมยังขาย
for (const p of PARTS) if (['e', 'm', 'f', 'j'].includes(p.slot)) FREE.add(p.id)
// ตัวแปรสีใช้ราคาพิเศษของชิ้นแม่ด้วย (19 พ.ย. — เดิมผ้าพันคอพลิ้วลมดำหลุดไปราคาธีมปกติ)
for (const p of PARTS) p.price = FREE.has(p.id) ? 0 : (PRICE_OVERRIDE[p.id] ?? PRICE_OVERRIDE[p.variantOf] ?? THEME_PRICE[p.theme] ?? 8000)

// ✨ ออร่าของแพง (19 พ.ย. 2026) — ใส่ชิ้นไหนก็มีออร่าของชิ้นที่แพงที่สุด · DollFigure วาดเป็น CSS เบาๆ
// sparkle = ประกายพิกเซลกระพริบรอบตัว · glow = เรืองแสงนุ่มรอบขอบ
// 🔗 ใส่คู่กันแล้วไม่ซ้อน (user 19 พ.ย.): ชุด = ออร่ารอบตัว (glow/ring) · หมวก/ปีก/ผ้าคลุม = อนุภาค (ดู utils/dollAura.js)
// ⚠️ ห้ามใส่คอมเมนต์ // ท้ายบรรทัดที่มีหลาย id — เคยกิน id ที่ตามมาจนออร่าหายเงียบ (มีเทสต์คุม)
const AURA = {
  // ── ปีก/ผ้าคลุม = อนุภาค ──
  w1: { type: 'petals', color: '#FFFFFF' },        // ปีกนางฟ้า: ขนนกปลิว
  w7: { type: 'sparkle', color: '#FFFFFF' },       // ปีกนางฟ้าจิ๋ว
  w3: { type: 'stardust', color: '#F7B6C8' },      // ปีกแฟรี่: ละอองชมพู
  w4: { type: 'petals', color: '#F6C453' },        // ปีกผีเสื้อ
  w2: { type: 'stardust', color: '#9B6BD9' },      // ปีกค้างคาว
  w5: { type: 'flame', color: '#F6A04D' },         // ปีกมังกร: เปลวไฟที่เท้า
  w6: { type: 'sparkle', color: '#FFB3AC' },       // ผ้าคลุมฮีโร่
  // ── หมวก = อนุภาค ──
  x39: { type: 'sparkle', color: '#EEF4FF' },      // หมวกอัศวิน
  x40: { type: 'hearts', color: '#F29BB5' },       // มงกุฎเจ้าหญิง
  x41: { type: 'stardust', color: '#C9B8FF' },     // หมวกผู้วิเศษ
  x3: { type: 'sparkle', color: '#FFE7A8' },      // มงกุฎ (คู่กับชุดเจ้าชายที่เป็นวงใต้เท้า)
  // ── ชุด = รอบตัว ──
  f3: { type: 'glow', color: '#FFE7A8' }, f6: { type: 'glow', color: '#7FC8B5' },
  f19: { type: 'glow', color: '#BFD7FF' }, f20: { type: 'glow', color: '#FFB8D9' }, f21: { type: 'ring', color: '#F6C453' },
  f22: { type: 'glow', color: '#B49BE0' }, f23: { type: 'glow', color: '#F08A80' }, f24: { type: 'glow', color: '#F6D77A' },
  f25: { type: 'glow', color: '#8FB0EA' }, f26: { type: 'glow', color: '#7FD3A8' },
  f14: { type: 'bubbles', color: '#FFB3AC' },      // มาสคอตแคปซูล: ฟองลอย
  // ชุดวอร์มสุดเนี้ยบ: ประกายระยิบ (user ชอบแบบเดิม)
  f15: { type: 'sparkle', color: '#DDEBFF' }, f16: { type: 'sparkle', color: '#C9C9D6' }, f17: { type: 'sparkle', color: '#FFB3AC' }, f18: { type: 'sparkle', color: '#A8C2EE' },
}
for (const p of PARTS) { const a = AURA[p.id] ?? AURA[p.variantOf]; if (a) p.aura = a; else delete p.aura }

